WHERE source_host = 'h' AND source_name = 'codex' AND doc_id IN (SELECT event_uid FROM `moraine`.search_documents WHERE (source_host, source_name, source_file, source_generation) IN (('h', 'codex', '/dup.jsonl', toUInt32(5))));

