DELETE FROM `moraine`.tool_io
WHERE (source_host, source_name, event_uid) IN (SELECT source_host, source_name, event_uid FROM `moraine`.events WHERE (source_host, source_name, source_file, source_generation) IN (('h', 'codex', '/dup.jsonl', toUInt32(5))));

-- delete 4: event_links
DELETE FROM `moraine`.event_links
WHERE (source_host, source_name, event_uid) IN (SELECT source_host, source_name, event_uid FROM `moraine`.events WHERE (source_host, source_name, source_file, source_generation) IN (('h', 'codex', '/dup.jsonl', toUInt32(5))));

SELECT 'mid-unit' AS at, src, toUInt64(count()) AS reader_visible_rows
FROM (
  SELECT 'events' AS src
  FROM (SELECT * FROM moraine.events FINAL) AS e
  ALL INNER JOIN moraine.v_current_published_source_generations AS h
    ON e.source_host = h.source_host AND e.source_name = h.source_name
   AND e.source_file = h.source_file AND e.source_generation = h.source_generation
  UNION ALL
  SELECT 'documents' AS src
  FROM (SELECT * FROM moraine.search_documents FINAL) AS d
  ALL INNER JOIN moraine.v_current_published_source_generations AS h
    ON d.source_host = h.source_host AND d.source_name = h.source_name
   AND d.source_file = h.source_file AND d.source_generation = h.source_generation
  WHERE d.doc_len > 0
  UNION ALL
  SELECT 'tool_io' AS src
  FROM (SELECT * FROM moraine.tool_io FINAL) AS t
  ALL INNER JOIN (
    SELECT e.source_host AS source_host, e.event_uid AS event_uid, e.event_version AS event_version
    FROM (SELECT * FROM moraine.events FINAL) AS e
    ALL INNER JOIN moraine.v_current_published_source_generations AS h
      ON e.source_host = h.source_host AND e.source_name = h.source_name
     AND e.source_file = h.source_file AND e.source_generation = h.source_generation
  ) AS le ON t.source_host = le.source_host AND t.event_uid = le.event_uid
   AND t.source_event_version != 0 AND t.source_event_version = le.event_version
  UNION ALL
  SELECT 'event_links' AS src
  FROM (SELECT * FROM moraine.event_links FINAL) AS l
  ALL INNER JOIN (
    SELECT e.source_host AS source_host, e.event_uid AS event_uid, e.event_version AS event_version
    FROM (SELECT * FROM moraine.events FINAL) AS e
    ALL INNER JOIN moraine.v_current_published_source_generations AS h
      ON e.source_host = h.source_host AND e.source_name = h.source_name
     AND e.source_file = h.source_file AND e.source_generation = h.source_generation
  ) AS le ON l.source_host = le.source_host AND l.event_uid = le.event_uid
   AND l.source_event_version != 0 AND l.source_event_version = le.event_version
)
GROUP BY src
ORDER BY src ASC
FORMAT TSVWithNames;

