SELECT 'after' AS at, src, gen_tag, toUInt64(count()) AS physical_rows
FROM (
  SELECT 'events' AS src, concat(source_file, '#', toString(source_generation), '@', source_name) AS gen_tag FROM moraine.events
  UNION ALL SELECT 'raw_events', concat(source_file, '#', toString(source_generation), '@', source_name) FROM moraine.raw_events
  UNION ALL SELECT 'ingest_errors', concat(source_file, '#', toString(source_generation), '@', source_name) FROM moraine.ingest_errors
  UNION ALL SELECT 'search_documents', concat(source_file, '#', toString(source_generation), '@', source_name) FROM moraine.search_documents
  UNION ALL SELECT 'search_postings', concat('uid:', substring(doc_id, 1, 2), '@', source_name) FROM moraine.search_postings
  UNION ALL SELECT 'tool_io', concat('uid:', substring(event_uid, 1, 2), '@', source_name) FROM moraine.tool_io
  UNION ALL SELECT 'event_links', concat('uid:', substring(event_uid, 1, 2), '@', source_name) FROM moraine.event_links
)
GROUP BY src, gen_tag
ORDER BY src ASC, gen_tag ASC
FORMAT TSVWithNames;
